 def test_dummy_and_ellipsis_subject_held(self):
  self.assertEqual({e['id']:e['source_sha256'] for e in self.r['held_entries']},{'coalesced:ce28f9a29400304ae5b0a8656237363473ff2fd21fc2522717318786ef45a65e': 'fddc591f5dfc27fc136ab2d664516ccc2c1f781d2a4d0e7da7fd555bb7bec6c4', 'coalesced:dd09d1629a475be2d0900e17e7680fb9e7bc9a9dbacbc117db34205fa5d42c32': '895361ffbf88d5a8c40d47f8dd3d03df2042ca9360d08738bcbb4faa39495404'});self.assertEqual({e['source_sha256'] for e in self.r['held_entries']},{hashlib.sha256('더미'.encode()).hexdigest(),hashlib.sha256(b'......').hexdigest()})
